var i=180;var a=`180-dough-hydration-and-consistency`;var n=`178`;var r={en:`Dough Hydration and Consistency`,ua:`Гідратація та консистенція тіста`};var o={short:`Hydration describes water relative to flour mass and is central to bread dough consistency. It influences stickiness, dough extensibility, fermentation, handling, and final crumb structure.`,sections:[{title:`Core idea`,text:`Baker’s hydration is commonly expressed as water mass divided by total flour mass, multiplied by 100%. For example, 700 g water with 1,000 g flour equals 70% hydration. Other water-containing ingredients complicate simple calculations.`},{title:`Scientific / practical principles`,text:`Water hydrates proteins and starch and enables enzymatic activity and fermentation. Higher hydration often gives softer, stickier dough and can support a more open crumb with suitable technique. Whole-grain and higher-absorption flours can feel firmer at the same numerical hydration.`},{title:`How to apply it`,text:`Weigh flour and water rather than relying on cup volume. Hold back a small portion of water when trying an unfamiliar flour, let the dough rest before judging consistency, and adjust gradually according to the intended bread and mixing method.`},{title:`Practical example`,text:`Make three doughs from 200 g of the same flour with 120 g, 140 g, and 160 g of water (60%, 70%, and 80%). After equal rest, compare spreading, stickiness, ability to shape, and stretch.`},{title:`Common mistakes and limitations`,text:`Higher hydration does not automatically mean better bread; flour and technique matter greatly. An enriched dough with eggs, milk, butter, or fruit contains additional water not always fully reflected in a simplified hydration formula.`},{title:`Related theories`,text:`178, 179, 181.`}]};var l={short:`Гідратація показує співвідношення води до маси борошна й визначає консистенцію хлібного тіста. Вона впливає на липкість, розтяжність, бродіння, зручність формування та структуру м’якушки.`,sections:[{title:`Суть`,text:`У пекарських відсотках гідратацію часто розраховують як масу води, поділену на загальну масу борошна, помножену на 100%. Наприклад, 700 г води та 1 000 г борошна становлять 70%. Яйця, молоко та інші складники ускладнюють простий розрахунок.`},{title:`Наукові та практичні принципи`,text:`Вода зволожує білки й крохмаль та забезпечує умови для роботи ферментів і дріжджів. Тісто з більшою гідратацією зазвичай м’якше та липкіше, а за належної техніки може дати відкритішу м’якушку. Цільнозернове борошно поглинає більше води.`},{title:`Як застосовувати`,text:`Зважуйте борошно й воду. З новим борошном спочатку залишайте трохи води осторонь, давайте тісту відпочити й лише тоді оцінюйте консистенцію. Додавайте воду поступово відповідно до бажаного хліба.`},{title:`Практичний приклад`,text:`Зробіть три заміси з 200 г однакового борошна й 120, 140 та 160 г води (60%, 70% і 80%). Після однакового відпочинку порівняйте липкість, розтікання, формування та розтягування.`},{title:`Поширені помилки й обмеження`,text:`Вища гідратація не гарантує кращий хліб: важливі борошно та навички. Здобне тісто з яйцями, молоком, маслом або фруктами містить додаткову воду, яку не завжди враховують у спрощеному розрахунку.`},{title:`Пов’язані теорії`,text:`178, 179, 181.`}]};var s=[178,179,181];var d=`References / Джерела`;var c=[`https://www.kingarthurbaking.com/blog/2023/01/11/bread-hydration`,`https://www.kingarthurbaking.com/blog/2021/08/18/a-beginners-guide-to-gluten`,`https://www.kingarthurbaking.com/learn/flour`];var h={id:180,slug:a,group:`178`,title:r,en:o,ua:l,related:s,referenceTitle:d,references:c};export{h as default,o as en,n as group,i as id,d as referenceTitle,c as references,s as related,a as slug,r as title,l as ua};